dashboard.definition:
{
    "title": "Overview",
    "description": "Events from your external attack surface, collected by the ShadowTrackr events input.",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Time range",
            "options": {
                "token": "global_time",
                "defaultValue": "-7d@h,now"
            }
        },
        "input_level": {
            "type": "input.dropdown",
            "title": "Alerts",
            "options": {
                "token": "min_level",
                "defaultValue": "90",
                "items": [
                    {
                        "label": "Problems only (90+)",
                        "value": "90"
                    },
                    {
                        "label": "Problems and warnings (80+)",
                        "value": "80"
                    }
                ]
            }
        },
        "input_org": {
            "type": "input.dropdown",
            "title": "Organization",
            "dataSources": {
                "primary": "ds_orgs"
            },
            "options": {
                "token": "org",
                "defaultValue": "*",
                "items": ">frame(label, value) | objects()"
            },
            "context": {
                "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)",
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                }
            }
        }
    },
    "defaults": {},
    "visualizations": {
        "viz_logo": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/shadowtrackr/images/logo_tile.png",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "https://shadowtrackr.com/usr/",
                        "newTab": true
                    }
                }
            ]
        },
        "viz_title": {
            "type": "splunk.markdown",
            "options": {
                "markdown": "## ShadowTrackr\nExternal attack surface monitoring \u00b7 [Open ShadowTrackr](https://shadowtrackr.com/usr/) \u00b7 [Documentation](https://shadowtrackr.com/docs)"
            }
        },
        "viz_total": {
            "type": "splunk.singlevalue",
            "title": "Events",
            "dataSources": {
                "primary": "ds_total"
            },
            "options": {
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            }
        },
        "viz_problems": {
            "type": "splunk.singlevalue",
            "title": "\u25b2 Problems (level 90+)",
            "dataSources": {
                "primary": "ds_problems"
            },
            "options": {
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "majorColor": "> majorValue | rangeValue(majorColorConfig)"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 1,
                        "value": "#c3c2b7"
                    },
                    {
                        "from": 1,
                        "to": 1000000000000000.0,
                        "value": "#d03b3b"
                    }
                ]
            }
        },
        "viz_warnings": {
            "type": "splunk.singlevalue",
            "title": "\u25a0 Warnings (level 80-89)",
            "dataSources": {
                "primary": "ds_warnings"
            },
            "options": {
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "majorColor": "> majorValue | rangeValue(majorColorConfig)"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 1,
                        "value": "#c3c2b7"
                    },
                    {
                        "from": 1,
                        "to": 1000000000000000.0,
                        "value": "#c98500"
                    }
                ]
            }
        },
        "viz_assets": {
            "type": "splunk.singlevalue",
            "title": "Assets with events",
            "dataSources": {
                "primary": "ds_assets"
            },
            "options": {
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            }
        },
        "viz_hosts": {
            "type": "splunk.singlevalue",
            "title": "Hosts",
            "dataSources": {
                "primary": "ds_hosts"
            },
            "options": {
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "sparklineStrokeColor": "#3987e5"
            }
        },
        "viz_websites": {
            "type": "splunk.singlevalue",
            "title": "Websites",
            "dataSources": {
                "primary": "ds_websites"
            },
            "options": {
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "sparklineStrokeColor": "#3987e5"
            }
        },
        "viz_certs": {
            "type": "splunk.singlevalue",
            "title": "Certificates",
            "dataSources": {
                "primary": "ds_certs"
            },
            "options": {
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "sparklineStrokeColor": "#3987e5"
            }
        },
        "viz_cves": {
            "type": "splunk.singlevalue",
            "title": "CVE findings",
            "dataSources": {
                "primary": "ds_cves"
            },
            "options": {
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "sparklineStrokeColor": "#3987e5"
            }
        },
        "viz_timeline": {
            "type": "splunk.column",
            "title": "Events over time",
            "dataSources": {
                "primary": "ds_timeline"
            },
            "options": {
                "stackMode": "stacked",
                "legendDisplay": "top",
                "seriesColorsByField": {
                    "Problems": "#d03b3b",
                    "Warnings": "#c98500",
                    "Info": "#3987e5"
                },
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide"
            }
        },
        "viz_category": {
            "type": "splunk.bar",
            "title": "Events by category",
            "dataSources": {
                "primary": "ds_category"
            },
            "options": {
                "legendDisplay": "off",
                "seriesColors": [
                    "#3987e5"
                ],
                "dataValuesDisplay": "all",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide"
            }
        },
        "viz_latest": {
            "type": "splunk.table",
            "title": "Latest alerts",
            "dataSources": {
                "primary": "ds_latest"
            },
            "options": {
                "count": 10
            },
            "description": "Problems only, or problems and warnings, depending on the Alerts filter. Click a row to see the event."
        },
        "viz_top_assets": {
            "type": "splunk.table",
            "title": "Assets with the most alerts",
            "dataSources": {
                "primary": "ds_top_assets"
            },
            "options": {
                "count": 9
            }
        },
        "viz_changes": {
            "type": "splunk.table",
            "title": "Top changes",
            "dataSources": {
                "primary": "ds_changes"
            },
            "options": {
                "count": 10
            }
        },
        "viz_unclassified": {
            "type": "splunk.table",
            "title": "Event types without a classification",
            "dataSources": {
                "primary": "ds_unclassified"
            },
            "options": {
                "count": 5
            },
            "description": "The app refreshes the event type catalogue from the API daily; types listed here are not in it yet.",
            "hideWhenNoData": true
        }
    },
    "dataSources": {
        "ds_total": {
            "type": "ds.search",
            "name": "Total events",
            "options": {
                "query": "`shadowtrackr_events` | where \"$org$\"=\"*\" OR vendor_account=\"$org$\" | stats count",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            }
        },
        "ds_problems": {
            "type": "ds.search",
            "name": "Problems",
            "options": {
                "query": "`shadowtrackr_events` | where \"$org$\"=\"*\" OR vendor_account=\"$org$\" | where level>=90 | stats count",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            }
        },
        "ds_warnings": {
            "type": "ds.search",
            "name": "Warnings",
            "options": {
                "query": "`shadowtrackr_events` | where \"$org$\"=\"*\" OR vendor_account=\"$org$\" | where level>=80 AND level<90 | stats count",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            }
        },
        "ds_assets": {
            "type": "ds.search",
            "name": "Assets with events",
            "options": {
                "query": "`shadowtrackr_events` | where \"$org$\"=\"*\" OR vendor_account=\"$org$\" | stats dc(dest) as assets",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            }
        },
        "ds_hosts": {
            "type": "ds.search",
            "name": "Hosts",
            "options": {
                "query": "`shadowtrackr_inventory_summary` status=ok type=hosts | where \"$org$\"=\"*\" OR organization=\"$org$\" | fillnull value=\"-\" organization | bin _time span=12h | stats latest(present) as present by _time, input, organization | timechart span=12h sum(present) as \"Hosts\"",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            }
        },
        "ds_websites": {
            "type": "ds.search",
            "name": "Websites",
            "options": {
                "query": "`shadowtrackr_inventory_summary` status=ok type=websites | where \"$org$\"=\"*\" OR organization=\"$org$\" | fillnull value=\"-\" organization | bin _time span=12h | stats latest(present) as present by _time, input, organization | timechart span=12h sum(present) as \"Websites\"",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            }
        },
        "ds_certs": {
            "type": "ds.search",
            "name": "Certificates",
            "options": {
                "query": "`shadowtrackr_inventory_summary` status=ok type=certificates | where \"$org$\"=\"*\" OR organization=\"$org$\" | fillnull value=\"-\" organization | bin _time span=12h | stats latest(present) as present by _time, input, organization | timechart span=12h sum(present) as \"Certificates\"",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            }
        },
        "ds_cves": {
            "type": "ds.search",
            "name": "CVEs",
            "options": {
                "query": "`shadowtrackr_inventory_summary` status=ok type=cves | where \"$org$\"=\"*\" OR organization=\"$org$\" | fillnull value=\"-\" organization | bin _time span=12h | stats latest(present) as present by _time, input, organization | timechart span=12h sum(present) as \"CVE findings\"",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            }
        },
        "ds_timeline": {
            "type": "ds.search",
            "name": "Events over time",
            "options": {
                "query": "`shadowtrackr_events` | where \"$org$\"=\"*\" OR vendor_account=\"$org$\" | eval Status=case(level>=90, \"Problems\", level>=80, \"Warnings\", true(), \"Info\") | timechart count by Status | fillnull value=0 Problems Warnings Info | table _time Problems Warnings Info",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            }
        },
        "ds_category": {
            "type": "ds.search",
            "name": "Events by category",
            "options": {
                "query": "`shadowtrackr_events` | where \"$org$\"=\"*\" OR vendor_account=\"$org$\" | eval Category=coalesce(st_category, \"unclassified\") | stats count as Events by Category | sort - Events",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            }
        },
        "ds_latest": {
            "type": "ds.search",
            "name": "Latest alerts",
            "options": {
                "query": "`shadowtrackr_events` | where \"$org$\"=\"*\" OR vendor_account=\"$org$\" | where level>=$min_level$ | sort - _time | head 100 | eval Status=case(level>=90, \"\u25b2 Problem\", level>=80, \"\u25a0 Warning\", true(), \"\u25cf Info\") | eval Time=strftime(_time, \"%Y-%m-%d %H:%M\") | rename dest AS Asset, signature AS Alert | table Time Status Asset Alert",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            }
        },
        "ds_top_assets": {
            "type": "ds.search",
            "name": "Assets with most alerts",
            "options": {
                "query": "`shadowtrackr_events` | where \"$org$\"=\"*\" OR vendor_account=\"$org$\" | where level>=$min_level$ | stats count as Alerts max(level) as level latest(signature) as \"Latest alert\" by dest | sort - level - Alerts | head 20 | eval Status=case(level>=90, \"\u25b2 Problem\", level>=80, \"\u25a0 Warning\", true(), \"\u25cf Info\") | rename dest AS Asset | table Asset Status Alerts \"Latest alert\"",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            }
        },
        "ds_changes": {
            "type": "ds.search",
            "name": "Changes by type",
            "options": {
                "query": "`shadowtrackr_events` | where \"$org$\"=\"*\" OR vendor_account=\"$org$\" | search eventtype=shadowtrackr_change | stats count as Changes by signature | rename signature AS Change | sort - Changes | head 10",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            }
        },
        "ds_unclassified": {
            "type": "ds.search",
            "name": "Unclassified event types",
            "options": {
                "query": "`shadowtrackr_events` | where \"$org$\"=\"*\" OR vendor_account=\"$org$\" | search NOT signature=* | stats count as Events latest(message) as Example by eventid category | rename eventid AS \"Event id\", category AS Source | sort - Events",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            }
        },
        "ds_orgs": {
            "type": "ds.search",
            "name": "Organizations",
            "options": {
                "query": "`shadowtrackr_events` vendor_account=* | stats count by vendor_account | rename vendor_account AS org_name | eval label=org_name, value=org_name, order=1 | append [| makeresults | eval label=\"All organizations\", value=\"*\", order=0] | sort order label | table label value",
                "queryParameters": {
                    "earliest": "-30d",
                    "latest": "now"
                }
            }
        }
    },
    "layout": {
        "type": "grid",
        "options": {
            "width": 1200
        },
        "globalInputs": [
            "input_time",
            "input_level",
            "input_org"
        ],
        "structure": [
            {
                "item": "viz_logo",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 0,
                    "w": 90,
                    "h": 90
                }
            },
            {
                "item": "viz_title",
                "type": "block",
                "position": {
                    "x": 90,
                    "y": 0,
                    "w": 1110,
                    "h": 90
                }
            },
            {
                "item": "viz_total",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 90,
                    "w": 300,
                    "h": 110
                }
            },
            {
                "item": "viz_problems",
                "type": "block",
                "position": {
                    "x": 300,
                    "y": 90,
                    "w": 300,
                    "h": 110
                }
            },
            {
                "item": "viz_warnings",
                "type": "block",
                "position": {
                    "x": 600,
                    "y": 90,
                    "w": 300,
                    "h": 110
                }
            },
            {
                "item": "viz_assets",
                "type": "block",
                "position": {
                    "x": 900,
                    "y": 90,
                    "w": 300,
                    "h": 110
                }
            },
            {
                "item": "viz_hosts",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 200,
                    "w": 300,
                    "h": 120
                }
            },
            {
                "item": "viz_websites",
                "type": "block",
                "position": {
                    "x": 300,
                    "y": 200,
                    "w": 300,
                    "h": 120
                }
            },
            {
                "item": "viz_certs",
                "type": "block",
                "position": {
                    "x": 600,
                    "y": 200,
                    "w": 300,
                    "h": 120
                }
            },
            {
                "item": "viz_cves",
                "type": "block",
                "position": {
                    "x": 900,
                    "y": 200,
                    "w": 300,
                    "h": 120
                }
            },
            {
                "item": "viz_timeline",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 320,
                    "w": 800,
                    "h": 320
                }
            },
            {
                "item": "viz_category",
                "type": "block",
                "position": {
                    "x": 800,
                    "y": 320,
                    "w": 400,
                    "h": 320
                }
            },
            {
                "item": "viz_latest",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 640,
                    "w": 1200,
                    "h": 400
                }
            },
            {
                "item": "viz_top_assets",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 1040,
                    "w": 760,
                    "h": 440
                }
            },
            {
                "item": "viz_changes",
                "type": "block",
                "position": {
                    "x": 760,
                    "y": 1040,
                    "w": 440,
                    "h": 440
                }
            },
            {
                "item": "viz_unclassified",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 1480,
                    "w": 1200,
                    "h": 250
                }
            }
        ]
    }
}
